import * as React from "react"

import { cn } from "@/lib/utils"
import { Scrollbar } from "@/components/ui/scrollbar"

/**
 * A box that scrolls. A rule appears at an edge only while there's more beyond it, and the
 * scrollbar is the ruler rail. Give it a height (or max-height) and a name: it takes focus
 * so the keyboard can scroll it, and a name says what it holds.
 */
function ScrollArea({ className, children, ...props }: React.ComponentProps<"div">) {
  const named = props["aria-label"] || props["aria-labelledby"]
  return (
    <div data-slot="scroll-area" tabIndex={0} role={named ? "region" : undefined} className={cn("db-scroll", className)} {...props}>
      {children}
      <Scrollbar variant="inner" />
    </div>
  )
}

export { ScrollArea }

@layer components {
  /* ── db-scroll ── a rule appears at an edge only while there's more beyond it */
  .db-scroll {
    overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--db-rule-strong) transparent;
    /* The paper covering each rule scrolls with the content; the rules stay put. */
    background:
      linear-gradient(var(--db-paper), var(--db-paper)) 0 0 / 100% 2px no-repeat local,
      linear-gradient(var(--db-paper), var(--db-paper)) 0 100% / 100% 2px no-repeat local,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) 0 0 / 100% var(--db-hairline) no-repeat scroll,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) 0 100% / 100% var(--db-hairline) no-repeat scroll;
  }
}
